return items.map((item) => {
  const raw = item.json.body || item.json;
  const entries = Array.isArray(raw.entry) ? raw.entry : [];
  const changes = entries.flatMap((entry) => Array.isArray(entry.changes) ? entry.changes : []);
  const change = changes[0] || {};
  const value = change.value || raw.value || raw;
  const message = Array.isArray(value.messages) ? value.messages[0] : null;
  const contact = Array.isArray(value.contacts) ? value.contacts[0] : null;
  const status = Array.isArray(value.statuses) ? value.statuses[0] : null;

  const extractMessageText = (source) => {
    if (!source) return '';
    return (
      source.text?.body ||
      source.button?.text ||
      source.interactive?.button_reply?.title ||
      source.interactive?.list_reply?.title ||
      source.image?.caption ||
      source.video?.caption ||
      source.document?.caption ||
      source.caption ||
      source.conversation ||
      ''
    ).toString().trim();
  };

  const fallbackBody = raw.query || raw.body || raw;
  const fallbackMessage = (fallbackBody.mensagem || fallbackBody.message || fallbackBody.text || '').toString().trim();

  if (!message && !fallbackMessage) {
    return [{
      json: {
        kind: status ? 'status' : 'ignored',
        id_candidato: 'ricardo-vale',
        eleitor_id: '',
        eleitor_uid: '',
        nome: '',
        telefone: '',
        email: '',
        cidade: '',
        bairro: '',
        mensagem_eleitor: '',
        tema_interesse: 'geral',
        intencao_voto: 'nao_classificada',
        sentimento: 'neutro',
        etapa_sugerida: 'novo_lead',
        score_delta: 0,
        consentimento_lgpd: true,
        canal_preferido: 'whatsapp',
        origem_captacao: 'meta_cloud_api',
        rotulo_ia: 'Resposta operacional de validação da campanha.',
        mensagem_resposta: '',
        metadata: raw,
        status_event: status || null,
        response_message: status ? 'Evento de status recebido com sucesso.' : 'Evento recebido sem mensagem de eleitor.'
      }
    }];
  }

  const telefone = String(message?.from || fallbackBody.telefone || fallbackBody.phone || '').replace(/\D/g, '');
  const email = (fallbackBody.email || '').toString().trim();
  const eleitorId = (fallbackBody.eleitor_id || telefone || email || Date.now().toString()).toString().trim();
  const mensagem = extractMessageText(message) || fallbackMessage;
  const nome = (contact?.profile?.name || fallbackBody.nome || fallbackBody.name || 'Eleitor').toString().trim();
  const mensagemLc = mensagem.toLowerCase();

  let tema = 'geral';
  if (mensagemLc.includes('educa')) tema = 'educacao';
  else if (mensagemLc.includes('saud')) tema = 'saude';
  else if (mensagemLc.includes('seguran')) tema = 'seguranca';
  else if (mensagemLc.includes('trabalho') || mensagemLc.includes('emprego')) tema = 'trabalho';
  else if (mensagemLc.includes('mobilidade') || mensagemLc.includes('transporte')) tema = 'mobilidade';

  let intencao = 'nao_classificada';
  if (mensagemLc.includes('apoio') || mensagemLc.includes('voto')) intencao = 'apoio';
  else if (mensagemLc.includes('duvida') || mensagemLc.includes('talvez')) intencao = 'indeciso';

  let sentimento = 'neutro';
  if (mensagemLc.includes('parab') || mensagemLc.includes('gostei') || mensagemLc.includes('apoio')) sentimento = 'positivo';
  else if (mensagemLc.includes('reclama') || mensagemLc.includes('ruim') || mensagemLc.includes('contra')) sentimento = 'negativo';

  let etapa = 'qualificado';
  if (intencao === 'apoio') etapa = 'engajado';
  if (!mensagem) etapa = 'novo_lead';

  const respostaBase = {
    educacao: 'Obrigado pela mensagem. O time do Ricardo Vale registrou seu interesse em educação e retornará com conteúdo qualificado.',
    saude: 'Obrigado pelo contato. O time do Ricardo Vale registrou seu interesse em saúde para aprofundar esse tema com você.',
    seguranca: 'Recebemos sua mensagem. O tema segurança já foi sinalizado para o relacionamento da campanha do Ricardo Vale.',
    trabalho: 'Obrigado pela mensagem. Registramos seu interesse em trabalho e desenvolvimento para a campanha do Ricardo Vale.',
    mobilidade: 'Recebemos sua mensagem. O tema mobilidade foi associado ao seu cadastro para continuidade do relacionamento.',
    geral: 'Obrigado pela mensagem. Seu contato foi registrado na campanha do Ricardo Vale e seguirá para acompanhamento.'
  };

  return [{
    json: {
      kind: 'inbound',
      id_candidato: 'ricardo-vale',
      eleitor_id: eleitorId,
      eleitor_uid: `ricardo-vale:${eleitorId}`,
      nome,
      telefone,
      email,
      cidade: (fallbackBody.cidade || '').toString().trim(),
      bairro: (fallbackBody.bairro || '').toString().trim(),
      mensagem_eleitor: mensagem,
      tema_interesse: tema,
      intencao_voto: intencao,
      sentimento,
      etapa_sugerida: etapa,
      score_delta: intencao === 'apoio' ? 20 : 8,
      consentimento_lgpd: fallbackBody.consentimento_lgpd !== false,
      canal_preferido: 'whatsapp',
      origem_captacao: 'meta_cloud_api',
      rotulo_ia: 'Este atendimento é realizado por assistente virtual oficial da campanha.',
      mensagem_resposta: `Este atendimento é realizado por assistente virtual oficial da campanha.\n\n${respostaBase[tema]}`,
      metadata: raw,
      meta_phone_number_id: value.metadata?.phone_number_id || '',
      meta_display_phone_number: value.metadata?.display_phone_number || '',
      meta_message_id: message?.id || '',
      response_message: 'Mensagem inbound recebida e processada com sucesso.'
    }
  }];
});

function pick(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    const text = String(value).trim();
    if (text) return text;
  }
  return '';
}

function normalizePhone(value) {
  const digits = String(value || '').replace(/\D/g, '');
  if (!digits) return '';
  if (digits.startsWith('55')) return digits;
  if (digits.length >= 10 && digits.length <= 11) return '55' + digits;
  return digits;
}

function extractTaskId(text) {
  const explicit = String(text || '').match(/(?:taskId|tarefaId|tarefa|id da tarefa|#tarefa)\s*[:#=-]?\s*([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})/i);
  if (explicit && explicit[1]) return explicit[1];
  const generic = String(text || '').match(/\b([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\b/i);
  return generic && generic[1] ? generic[1] : '';
}

function extractQuantity(text, fallback) {
  const direct = Number(fallback);
  if (Number.isFinite(direct) && direct > 0) return Math.trunc(direct);
  const matched = String(text || '').match(/(?:qtd|quantidade|realizei|realizado|realizada|convidei|convide|convidados|contatos|convites|visitas|panfletos|moradores|pessoas|eleitores)\D{0,20}(\d{1,5})/i);
  if (matched && matched[1]) return Math.max(1, Math.trunc(Number(matched[1])));
  return 1;
}

return items.map((item) => {
  const body = item.json.body || item.json.raw || item.json.metadata || {};
  const idCandidato = 'ricardo-vale';
  const mensagem = pick(item.json.mensagem_eleitor, item.json.mensagem, item.json.message, item.json.text, body.mensagem, body.message, body.text);
  const explicitTaskId = pick(item.json.taskId, item.json.tarefaId, body.taskId, body.tarefaId, body.tarefa_id);
  const taskId = explicitTaskId || extractTaskId(mensagem);
  const telefone = normalizePhone(pick(item.json.telefone, item.json.memberPhone, item.json.whatsapp, body.telefone, body.memberPhone, body.whatsapp, body.from));
  const quantidadeValidada = extractQuantity(mensagem, pick(item.json.quantidadeValidada, item.json.quantidade, body.quantidadeValidada, body.quantidade));
  const n8nBase = pick($env.N8N_WEBHOOK_BASE_URL, $env.N8N_BASE_URL, $env.WEBHOOK_BASE_URL).replace(/\/$/, '');
  const webhookBase = n8nBase ? (n8nBase.endsWith('/webhook') ? n8nBase : n8nBase + '/webhook') : '';
  const errors = [];

  if (taskId && !telefone) errors.push('telefone do membro ausente para registrar evidencia de divulgacao.');
  if (taskId && !webhookBase) errors.push('N8N_WEBHOOK_BASE_URL nao configurada para acionar o workflow 22b.');

  return {
    json: {
      ...item.json,
      evidencia_divulgacao_detectada: Boolean(taskId),
      evidencia_divulgacao_valida: Boolean(taskId && telefone && webhookBase),
      evidencia_divulgacao_erros: errors,
      evidencia_divulgacao_payload: {
        idCandidato,
        taskId,
        telefone,
        mensagem,
        quantidade: quantidadeValidada,
        canal: 'whatsapp',
        origem: '02b-funil-whatsapp'
      },
      evidencia_divulgacao_webhook_url: taskId && webhookBase ? webhookBase + '/agente-politico/' + encodeURIComponent(idCandidato) + '/divulgacao/evidencias' : ''
    }
  };
});
